import XCTest
@testable import AmbulandoCore

/// The sidebar's Workspace → Scope → Channel read path against bodies produced by Tower's own serializers
/// (Fixtures/tower-navigation.json, regenerated by Fixtures/generate-tower-navigation.sh), plus the selection and
/// load-state rules that decide what the sidebar shows. Regression for builds 6–7: with no workspace ever chosen in the
/// switcher the sidebar never started reading scopes and stayed on "Loading navigation…".
final class NavigationLoadTests: XCTestCase {
    static let fixtureURL = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("Fixtures/tower-navigation.json")
    static let w1 = "2e5caefd-0000-4000-8000-0000000000a1", w2 = "2e5caefd-0000-4000-8000-0000000000a2"
    static let origin = "https://tower.example"

    struct Bodies: @unchecked Sendable {
        let workspaces: [String: Any]
        let scopes: [String: Any]
        let channels: [String: Any]
    }

    func bodies() throws -> Bodies {
        let object = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(contentsOf: Self.fixtureURL)) as? [String: Any])
        return Bodies(workspaces: try XCTUnwrap(object["workspaces"] as? [String: Any]),
                      scopes: try XCTUnwrap(object["scopes"] as? [String: Any]),
                      channels: try XCTUnwrap(object["channels"] as? [String: Any]))
    }

    /// Answers the navigation routes with the generated Tower bodies; `scopesStatus` overrides the scope list status.
    func routes(_ b: Bodies, scopesStatus: @escaping @Sendable () -> Int = { 200 }) -> StubTransport.Handler {
        { request in
            let path = request.url!.path
            let base = "/api/v4/flightdeck-pg/workspaces"
            if path == "/.well-known/nstack.json" { return (200, Fixtures.descriptor(origin: Self.origin)) }
            if path == base { return (200, b.workspaces) }
            let parts = path.replacingOccurrences(of: base + "/", with: "").split(separator: "/").map(String.init)
            switch (parts.count, parts.count > 1 ? parts[1] : "") {
            case (2, "scopes"):
                let status = scopesStatus()
                return status == 200 ? (200, b.scopes[parts[0]] ?? ["scopes": [], "next_cursor": NSNull()])
                                     : (status, ["error": "Internal error", "code": "internal_error", "status": status])
            case (4, "scopes") where parts[3] == "channels":
                return (200, b.channels[parts[2]] ?? ["channels": [], "next_cursor": NSNull()])
            case (2, "members"): return (200, ["members": [], "next_cursor": NSNull()])
            case (3, "me"): return (200, ["scope_order": ["scope_ids": [], "row_version": 1]])
            case (4, "channels") where parts[3] == "messages": return (200, ["messages": [], "next_cursor": NSNull()])
            case (4, "channels") where parts[3] == "threads": return (200, ["threads": [], "next_cursor": NSNull()])
            default: return (404, ["error": "Not found", "code": "not_found", "status": 404])
            }
        }
    }

    func testTowerShapedNavigationLoadsWithNoWorkspaceEverChosen() async throws {
        let b = try bodies()
        let identity = try await makeIdentity()
        let store = try LocalStore(directory: temporaryDirectory())
        let transport = StubTransport(routes(b))
        let sync = WorkspaceSync(store: store, engine: SyncEngine(), identity: identity, transport: transport)
        let connection = try await sync.connect(origin: try TowerOrigin(Self.origin))
        await sync.discover(connection)
        await sync.engine.waitUntilIdle()

        // Nothing persisted "selected.workspace": the state of everyone who never opened the switcher.
        let persisted = try await store.reader.state("selected.workspace:\(connection.id)")
        XCTAssertNil(persisted)
        let listed = try await store.reader.workspaces(connectionId: connection.id)
        XCTAssertEqual(Set(listed.map(\.label)), ["Wingman", "Other Stuff"])
        let complete = try await store.reader.state(WorkspaceSelection.listedKey(connection.id)) != nil
        XCTAssertTrue(complete, "Tower's list is recorded as authoritative with the rows")
        let shown = try XCTUnwrap(WorkspaceSelection.effective(persisted: persisted, listed: listed, listComplete: complete))
        XCTAssertEqual(shown, listed.first?.id)
        XCTAssertEqual(WorkspaceSelection.change(selected: nil, navigationFor: nil, listed: listed, listComplete: complete), .show(shown),
                       "the list arriving after launch (fresh connect) shows a workspace and starts its sidebar")

        for workspace in [Self.w1, Self.w2] {
            let groups = SidebarNavigation.groups(scopes: try await store.reader.scopes(workspaceId: workspace),
                                                  channels: try await store.reader.channels(workspaceId: workspace), personalOrder: [])
            if workspace == Self.w1 {
                XCTAssertEqual(groups.map(\.scope.name), ["DMs", "Ambulando", "Operations"], "direct messages first, then default order")
                XCTAssertEqual(groups[1].channels.map(\.name), ["general", "native app"], "position 1 before an unpositioned channel")
                XCTAssertEqual(groups[2].channels, [], "a scope without channels is still listed")
                XCTAssertTrue(SidebarNavigation.isDirectMessageChannel(try XCTUnwrap(groups[0].channels.first)))
            } else {
                XCTAssertEqual(groups.map(\.scope.name), ["Studio"])
                XCTAssertEqual(groups[0].channels.map(\.name), ["ideas", "studio"])
            }
        }

        let snapshot = await sync.engine.snapshot
        XCTAssertNil(WorkspaceSync.navigationError(snapshot, connectionId: connection.id, workspaceId: shown))
        XCTAssertFalse(WorkspaceSync.navigationRefreshing(snapshot, connectionId: connection.id, workspaceId: shown))

        // Workspace-scoped list reads name the workspace's app namespace and ask for Tower's maximum page.
        let navigationRequests = transport.recorded.filter { $0.url!.path.hasSuffix("/scopes") || $0.url!.path.hasSuffix("/channels") }
        XCTAssertEqual(navigationRequests.count, 2 + 4, "2 scope lists + 4 channel lists")
        for request in navigationRequests {
            XCTAssertEqual(request.value(forHTTPHeaderField: "x-flightdeck-pg-app-npub"), TestKeys.npub)
            XCTAssertEqual(URLComponents(url: request.url!, resolvingAgainstBaseURL: false)?.queryItems?.first { $0.name == "limit" }?.value, "200")
            XCTAssertEqual(try decodeAuthorization(request).tags.first, ["u", request.url!.absoluteString])
        }
    }

    func testFailedScopeRefreshIsReportedNotShownAsEmpty() async throws {
        let b = try bodies()
        let identity = try await makeIdentity()
        let store = try LocalStore(directory: temporaryDirectory())
        let status = LockedValue(500)
        let transport = StubTransport(routes(b, scopesStatus: { status.value }))
        let sync = WorkspaceSync(store: store, engine: SyncEngine(), identity: identity, transport: transport)
        let connection = try await sync.connect(origin: try TowerOrigin(Self.origin))
        await sync.discover(connection)
        await sync.engine.waitUntilIdle()

        var snapshot = await sync.engine.snapshot
        let error = try XCTUnwrap(WorkspaceSync.navigationError(snapshot, connectionId: connection.id, workspaceId: Self.w1))
        XCTAssertTrue(error.contains("500") && error.contains("scope list"), error)
        let none = try await store.reader.scopes(workspaceId: Self.w1)
        XCTAssertEqual(NavigationLoadState.resolve(.init(hasWorkspace: true, workspacesLoaded: true, navigationLoaded: true, hasScopes: !none.isEmpty,
                                                         canRead: true, refreshing: false, error: error)), .failed(error))

        // Retry (forced, past the backoff) succeeds and clears the error.
        status.value = 200
        let stored = try await store.reader.workspaces(connectionId: connection.id)
        let workspace = try XCTUnwrap(stored.first { $0.id == Self.w1 })
        await sync.refreshWorkspace(connection, workspace, priority: .visible, force: true)
        await sync.engine.waitUntilIdle()
        snapshot = await sync.engine.snapshot
        XCTAssertNil(WorkspaceSync.navigationError(snapshot, connectionId: connection.id, workspaceId: Self.w1))
        let scopes = try await store.reader.scopes(workspaceId: Self.w1).count
        XCTAssertEqual(scopes, 3)

        // A later failure keeps the saved scopes on screen and says the list may be out of date.
        status.value = 503
        await sync.refreshWorkspace(connection, workspace, priority: .visible, force: true)
        await sync.engine.waitUntilIdle()
        snapshot = await sync.engine.snapshot
        let stale = try XCTUnwrap(WorkspaceSync.navigationError(snapshot, connectionId: connection.id, workspaceId: Self.w1))
        let kept = try await store.reader.scopes(workspaceId: Self.w1).count
        XCTAssertEqual(kept, 3, "a failed refresh never removes saved scopes")
        XCTAssertEqual(NavigationLoadState.resolve(.init(hasWorkspace: true, workspacesLoaded: true, navigationLoaded: true, hasScopes: true,
                                                         canRead: true, refreshing: false, error: stale)), .ready(refreshError: stale))
    }

    func testEffectiveWorkspace() throws {
        let listed = try [Self.w1, Self.w2].map { id in
            try WorkspaceRecord(raw: Fixtures.json(Fixtures.workspace(id, label: id)))
        }
        let gone = "2e5caefd-0000-4000-8000-0000000000ff"
        XCTAssertEqual(WorkspaceSelection.effective(persisted: nil, listed: listed, listComplete: true), Self.w1, "no choice: the first listed workspace")
        XCTAssertEqual(WorkspaceSelection.effective(persisted: Self.w2, listed: listed, listComplete: true), Self.w2, "a listed choice is kept")
        XCTAssertEqual(WorkspaceSelection.effective(persisted: gone, listed: listed, listComplete: true), Self.w1,
                       "a workspace Tower no longer lists falls back to one it does")
        XCTAssertEqual(WorkspaceSelection.effective(persisted: Self.w2, listed: [], listComplete: false), Self.w2,
                       "before any list is stored (first launch, offline) the choice is kept")
        XCTAssertNil(WorkspaceSelection.effective(persisted: Self.w2, listed: [], listComplete: true),
                     "Tower answered with no workspaces: a removed workspace does not linger")
        XCTAssertNil(WorkspaceSelection.effective(persisted: nil, listed: [], listComplete: false))
    }

    func testWorkspaceListChanges() throws {
        let listed = try [Self.w1, Self.w2].map { id in try WorkspaceRecord(raw: Fixtures.json(Fixtures.workspace(id, label: id))) }
        func change(_ selected: String?, _ navigation: String?, _ list: [WorkspaceRecord], complete: Bool = true) -> WorkspaceSelection.Change {
            WorkspaceSelection.change(selected: selected, navigationFor: navigation, listed: list, listComplete: complete)
        }
        // Every refresh stores the same list again: nothing is reset (context, drafts, boards, scroll).
        XCTAssertEqual(change(Self.w2, Self.w2, listed), .none)
        XCTAssertEqual(change(Self.w1, Self.w1, listed), .none)
        // Launch with no stored choice and an empty store; the list arrives afterwards.
        XCTAssertEqual(change(nil, nil, [], complete: false), .none, "nothing to show yet, nothing to clear")
        XCTAssertEqual(change(nil, nil, listed), .show(Self.w1))
        // A launch-time default whose sidebar was never started (the build 6–7 failure) is started, not left loading.
        XCTAssertEqual(change(Self.w1, nil, listed), .startNavigation(Self.w1))
        // The shown workspace is removed or access is lost.
        XCTAssertEqual(change(Self.w2, Self.w2, [listed[0]]), .show(Self.w1))
        XCTAssertEqual(change(Self.w2, Self.w2, [], complete: true), .clear, "no memberships left: everything for it is cleared")
        XCTAssertEqual(change(Self.w2, Self.w2, [], complete: false), .none, "not loaded is not the same as removed")
    }

    func testDisconnectForgetsTheListedMarker() async throws {
        let store = try LocalStore(directory: temporaryDirectory())
        let connection = try await store.writer.saveConnection(ConnectionRecord(origin: try TowerOrigin(Self.origin), signerNpub: TestKeys.npub, towerNpub: nil))
        try await store.writer.replaceWorkspaces(connectionId: connection.id, [])
        let listed = try await store.reader.state(WorkspaceSelection.listedKey(connection.id))
        XCTAssertNotNil(listed, "an empty answer from Tower is still an answer")
        try await store.writer.removeConnection(id: connection.id)
        let after = try await store.reader.state(WorkspaceSelection.listedKey(connection.id))
        XCTAssertNil(after)
    }

    func testLoadStateNeverShowsNothingWithoutAReason() {
        func state(hasWorkspace: Bool = true, workspacesLoaded: Bool = true, navigationLoaded: Bool = true, hasScopes: Bool = false,
                   canRead: Bool = true, refreshing: Bool = false, error: String? = nil) -> NavigationLoadState {
            .resolve(.init(hasWorkspace: hasWorkspace, workspacesLoaded: workspacesLoaded, navigationLoaded: navigationLoaded,
                           hasScopes: hasScopes, canRead: canRead, refreshing: refreshing, error: error))
        }
        XCTAssertEqual(state(hasWorkspace: false, workspacesLoaded: false), .findingWorkspaces)
        XCTAssertEqual(state(hasWorkspace: false, refreshing: true), .findingWorkspaces)
        XCTAssertEqual(state(hasWorkspace: false, error: "HTTP 401"), .workspacesFailed("HTTP 401"))
        XCTAssertEqual(state(hasWorkspace: false, canRead: false), .locked)
        XCTAssertEqual(state(hasWorkspace: false), .noWorkspaces)
        XCTAssertEqual(state(navigationLoaded: false), .loading)
        XCTAssertEqual(state(refreshing: true), .loading)
        XCTAssertEqual(state(error: "HTTP 500"), .failed("HTTP 500"))
        XCTAssertEqual(state(canRead: false), .locked)
        XCTAssertEqual(state(), .empty)
        XCTAssertEqual(state(hasScopes: true), .ready(refreshError: nil))
        XCTAssertEqual(state(hasScopes: true, error: "offline"), .ready(refreshError: "offline"))
        XCTAssertEqual(state(hasScopes: true, refreshing: true, error: "offline"), .ready(refreshError: nil), "a retry in progress hides the old error")
    }

    func testNavigationKeysAreScopedToTheWorkspace() {
        let snapshot = SyncSnapshot(running: ["channels:\(Self.w2):s"], queued: [], scheduled: ["scopes:\(Self.w1)"],
                                    errors: ["messages:\(Self.w1):c": "unrelated", "scopes:\(Self.w2)": "other workspace"])
        XCTAssertFalse(WorkspaceSync.navigationRefreshing(snapshot, connectionId: "c", workspaceId: Self.w1), "a scheduled retry is not running")
        XCTAssertTrue(WorkspaceSync.navigationRefreshing(snapshot, connectionId: "c", workspaceId: Self.w2))
        XCTAssertNil(WorkspaceSync.navigationError(snapshot, connectionId: "c", workspaceId: Self.w1), "message and other-workspace errors are not sidebar errors")
        XCTAssertEqual(WorkspaceSync.navigationError(snapshot, connectionId: "c", workspaceId: Self.w2), "other workspace")
        var discovery = snapshot
        discovery.errors["discover:c"] = "HTTP 401"
        XCTAssertEqual(WorkspaceSync.navigationError(discovery, connectionId: "c", workspaceId: Self.w2), "HTTP 401")
    }
}

final class LockedValue<T: Sendable>: @unchecked Sendable {
    private let lock = NSLock()
    private var stored: T
    init(_ value: T) { stored = value }
    var value: T {
        get { lock.withLock { stored } }
        set { lock.withLock { stored = newValue } }
    }
}
